-- Close the item-less JSON Schema arrays in
-- `generate-executable-capability-scaffold`'s contracts so the node projector
-- can build a type for them, and `sfx capability prepare` stops throwing
--   "Array schema at '...#/properties/findings' has no admitted item schema."
--
-- Generated by docs/research/scaffold-projection-gap/build-contract-fix.mjs
-- against estate_model_pk 3 / estate_snapshot_pk 2. Digests and row keys below
-- were read live; the preconditions re-check them, so a moved row aborts.
--
-- ENDS IN ROLLBACK. Read the output, then change the last line to COMMIT.
--
-- ====================================================================
-- READ THIS FIRST -- this bypasses the immutability design
-- ====================================================================
-- source.content_object, source.source_appearance and model.schema_object each
-- carry an AFTER INSERT,UPDATE,DELETE guard whose body ends with:
--
--   IF EXISTS(SELECT 1 FROM deleted) THROW 51003,'IMMUTABLE_INSPECTION_DATA',1;
--
-- `deleted` is populated on UPDATE, so every UPDATE below throws while those
-- guards are enabled. This script disables the three triggers, repoints, then
-- re-enables them. That needs ALTER on those tables -- i.e. the owner, not
-- sidefx_importer, which is INSERT-only by grant.
--
-- What you trade away by doing it this way:
--
--   1. Capsule lineage stops being true. These documents are entries inside
--      capsules/generate-executable-capability-scaffold.sfxcap, whose digest
--      sha256:1964af7a... covers the OLD bytes. Afterwards the stored entry
--      bytes no longer hash into the capsule digest that
--      capability-embodiment.sql uses to resolve authority. Nothing here
--      re-packs the capsule or updates its digest.
--
--   2. The snapshot stops matching its source. estate_snapshot 2 was captured
--      from the harness working tree; re-running `npm run snapshot` or
--      `npm run derive` reproduces the ORIGINAL bytes and disagrees with these
--      rows.
--
--   3. Publication gates are not re-run here. source.validate_model and
--      `npm run verify` / `npm run check` are not executed by this script.
--      Run them after committing and expect lineage/digest findings.
--
--   4. Existing preparations are stale. All 94 rows in
--      runtime.capability_preparation were planned from pre-fix bytes. The
--      scaffold has none, so it is unaffected -- but any other capability
--      fixed this way needs its preparation rebuilt.
--
-- The supported alternative is to correct the source capsule and run
-- capture -> derive -> ingest -> publish, producing a new generation with
-- intact lineage. This script exists because you asked to make the data change
-- directly. It is a deliberate override, not the sanctioned path.
--
-- The byte change itself is safe and semantics-preserving:
--   {"type":"array"}  ->  {"type":"array","items":{}}
-- identical under Ajv (an empty schema admits any item) but projectable:
-- buildNode requires a non-array object at `items`, then resolves {} through
-- its existing typeless branch to { kind: "primitive", primitive: "unknown" }.
-- Verified locally: planNode produced 576 files across all 16 scaffold
-- scenarios once these 9 pointers were closed.
-- ====================================================================

SET NOCOUNT ON;
SET XACT_ABORT ON;

BEGIN TRANSACTION;

-- Preconditions. Abort unless the exact pre-fix rows are still present.
IF NOT EXISTS (SELECT 1 FROM source.content_object
               WHERE content_object_pk = 2116
                 AND content_digest = 0xF2E5A1CEC6B6FC7C8ADAA78DB82B66F2EF772968B6079255808BF758EC6AB533)
  THROW 60000, 'CARRIER_SCHEMA_NOT_AT_EXPECTED_DIGEST', 1;

IF NOT EXISTS (SELECT 1 FROM source.content_object
               WHERE content_object_pk = 2118
                 AND content_digest = 0x891EDA6469BE6D8E1935C5D69F70DD14C30BA0FD4D658558A0B33CFA450CAFD6)
  THROW 60000, 'INPUT_SCHEMA_NOT_AT_EXPECTED_DIGEST', 1;

-- The guards block UPDATE. Disabling them is the override described above.
ALTER TABLE source.content_object    DISABLE TRIGGER guard_content_object;
ALTER TABLE source.source_appearance DISABLE TRIGGER guard_source_appearance;
ALTER TABLE model.schema_object      DISABLE TRIGGER guard_schema_object;

--------------------------------------------------------------------------
-- contracts/carrier.schema.json
--   7 item-less array(s) closed with "items": {}
--   old  sha256:f2e5a1cec6b6fc7c8adaa78db82b66f2ef772968b6079255808bf758ec6ab533  1447 bytes  content_object_pk=2116
--   new  sha256:ba0ef882e1de4bf3fcf0f7368e6efb0e739d6df4b086251feaf6e830ef695df5  1580 bytes
--   source_appearance_pk 3705, 11864   schema_object_pk 194
--------------------------------------------------------------------------
IF NOT EXISTS (SELECT 1 FROM source.content_object WHERE content_digest = 0xBA0EF882E1DE4BF3FCF0F7368E6EFB0E739D6DF4B086251FEAF6E830EF695DF5)
  INSERT source.content_object (content_digest, content_bytes, byte_length)
  VALUES (0xBA0EF882E1DE4BF3FCF0F7368E6EFB0E739D6DF4B086251FEAF6E830EF695DF5, , 1580);

DECLARE @co_2116 bigint =
  (SELECT content_object_pk FROM source.content_object WHERE content_digest = 0xBA0EF882E1DE4BF3FCF0F7368E6EFB0E739D6DF4B086251FEAF6E830EF695DF5);

UPDATE source.source_appearance
   SET content_object_pk = @co_2116
 WHERE source_appearance_pk IN (3705, 11864)
   AND content_object_pk = 2116;
IF @@ROWCOUNT <> 2 THROW 60001, 'APPEARANCE_REPOINT_COUNT_UNEXPECTED', 1;

UPDATE model.schema_object
   SET content_object_pk = @co_2116, content_digest = 0xBA0EF882E1DE4BF3FCF0F7368E6EFB0E739D6DF4B086251FEAF6E830EF695DF5
 WHERE schema_object_pk = 194 AND content_object_pk = 2116;
IF @@ROWCOUNT <> 1 THROW 60002, 'SCHEMA_OBJECT_REPOINT_COUNT_UNEXPECTED', 1;

--------------------------------------------------------------------------
-- contracts/input.schema.json
--   2 item-less array(s) closed with "items": {}
--   old  sha256:891eda6469be6d8e1935c5d69f70dd14c30ba0fd4d658558a0b33cfa450cafd6  11998 bytes  content_object_pk=2118
--   new  sha256:c8c04604d941ed1b964f13a271981172463d9fdf01815ee93b2f90a1a691f13d  12076 bytes
--   source_appearance_pk 3707, 11866   schema_object_pk 193
--------------------------------------------------------------------------
IF NOT EXISTS (SELECT 1 FROM source.content_object WHERE content_digest = 0xC8C04604D941ED1B964F13A271981172463D9FDF01815EE93B2F90A1A691F13D)
  INSERT source.content_object (content_digest, content_bytes, byte_length)
  VALUES (0xC8C04604D941ED1B964F13A271981172463D9FDF01815EE93B2F90A1A691F13D, , 12076);

DECLARE @co_2118 bigint =
  (SELECT content_object_pk FROM source.content_object WHERE content_digest = 0xC8C04604D941ED1B964F13A271981172463D9FDF01815EE93B2F90A1A691F13D);

UPDATE source.source_appearance
   SET content_object_pk = @co_2118
 WHERE source_appearance_pk IN (3707, 11866)
   AND content_object_pk = 2118;
IF @@ROWCOUNT <> 2 THROW 60001, 'APPEARANCE_REPOINT_COUNT_UNEXPECTED', 1;

UPDATE model.schema_object
   SET content_object_pk = @co_2118, content_digest = 0xC8C04604D941ED1B964F13A271981172463D9FDF01815EE93B2F90A1A691F13D
 WHERE schema_object_pk = 193 AND content_object_pk = 2118;
IF @@ROWCOUNT <> 1 THROW 60002, 'SCHEMA_OBJECT_REPOINT_COUNT_UNEXPECTED', 1;

-- Re-enable the guards inside the same transaction.
ALTER TABLE source.content_object    ENABLE TRIGGER guard_content_object;
ALTER TABLE source.source_appearance ENABLE TRIGGER guard_source_appearance;
ALTER TABLE model.schema_object      ENABLE TRIGGER guard_schema_object;

-- Verification: expect 0 remaining item-less arrays for the scaffold.
WITH capsule AS (
  SELECT DISTINCT a.capsule_digest,
         JSON_VALUE(CAST(CONVERT(varchar(max), c.content_bytes) AS nvarchar(max)),'$.capabilityId') AS capability_id
  FROM source.source_appearance a
  JOIN source.content_object c ON c.content_object_pk = a.content_object_pk
  WHERE a.source_class = 'MANAGED_CAPSULE' AND a.entry_id = 'capability.authority.json'
),
schemas AS (
  SELECT DISTINCT k.capability_id, a.entry_id,
         CAST(CONVERT(varchar(max), c.content_bytes) AS nvarchar(max)) AS body
  FROM source.source_appearance a
  JOIN source.content_object c ON c.content_object_pk = a.content_object_pk
  JOIN capsule k ON k.capsule_digest = a.capsule_digest
  WHERE a.source_class = 'MANAGED_CAPSULE' AND a.entry_id LIKE 'contracts/%.schema.json'
    AND k.capability_id = 'generate-executable-capability-scaffold'
    AND ISJSON(CAST(CONVERT(varchar(max), c.content_bytes) AS nvarchar(max))) = 1
),
nodes AS (
  SELECT capability_id, entry_id, CAST('$' AS nvarchar(4000)) COLLATE DATABASE_DEFAULT AS path,
         CAST(body AS nvarchar(max)) AS node
  FROM schemas
  UNION ALL
  SELECT n.capability_id, n.entry_id,
         CAST(n.path + '.' + CAST(j.[key] AS nvarchar(400)) AS nvarchar(4000)) COLLATE DATABASE_DEFAULT,
         CAST(j.value AS nvarchar(max))
  FROM nodes n CROSS APPLY OPENJSON(n.node) j
  WHERE ISJSON(n.node) = 1 AND LEN(n.path) < 3000 AND j.type IN (4,5)
)
SELECT COUNT(*) AS remaining_open_arrays_expect_0
FROM nodes
WHERE ISJSON(node) = 1 AND JSON_VALUE(node,'$.type') = 'array' AND JSON_QUERY(node,'$.items') IS NULL
OPTION (MAXRECURSION 1000);

-- Inspect the result above, then swap ROLLBACK for COMMIT to keep it.
ROLLBACK TRANSACTION;
-- COMMIT TRANSACTION;
